import re
from typing import Dict, List, Tuple

def parse_ini(text: str) -> Dict[str, Dict[str, str]]:
    lines = text.splitlines()
    result: Dict[str, Dict[str, str]] = {}
    current_section: str = None
    default_section: Dict[str, str] = {}
    i = 0

    # Helper to strip and check if line is empty or comment
    def is_comment_or_empty(line: str) -> bool:
        stripped = line.strip()
        return len(stripped) == 0 or stripped[0] in (';', '#')

    # Helper to parse a key-value line
    def parse_key_value(line: str, section: str) -> Tuple[str, str]:
        # Strip leading/trailing whitespace
        line = line.strip()
        if not line:
            raise ValueError("Malformed line: empty after stripping")

        # Check for inline comment
        if ' ;' in line or ' #' in line:
            # Find first occurrence of ' ;' or ' #' after any leading whitespace
            # But only if it's not inside double quotes
            in_quotes = False
            comment_start = -1
            for j, char in enumerate(line):
                if char == '"':
                    in_quotes = not in_quotes
                elif not in_quotes and (char == ';' or char == '#'):
                    if j > 0 and line[j-1] == ' ':
                        comment_start = j
                        break

            if comment_start != -1:
                line = line[:comment_start].rstrip()

        # Check if line is empty after removing comment
        if not line:
            raise ValueError("Malformed line: empty after removing comment")

        # Split on first = or :, whichever comes first
        if '=' in line and ':' in line:
            split_pos = min(line.find('='), line.find(':'))
        elif '=' in line:
            split_pos = line.find('=')
        elif ':' in line:
            split_pos = line.find(':')
        else:
            raise ValueError(f"Malformed line: no '=' or ':' found in '{line}'")

        key_part = line[:split_pos].strip()
        value_part = line[split_pos + 1:].strip()

        # Check if value is quoted
        if value_part.startswith('"') and value_part.endswith('"'):
            value = value_part[1:-1]  # Remove quotes, keep everything inside
        else:
            value = value_part

        # Key is stripped and lowercased
        key = key_part.lower()

        # Validate key
        if not key:
            raise ValueError(f"Malformed line: empty key in '{line}'")

        return key, value

    # Helper to interpolate values
    def interpolate_value(value: str, section: str, all_sections: Dict[str, Dict[str, str]]) -> str:
        # Find all ${...} patterns
        pattern = r'\$\{([^}]+)\}'
        matches = re.findall(pattern, value)
        if not matches:
            return value

        # Process each match
        for match in matches:
            if ':' in match:
                # ${section:key}
                section_name, key_name = match.split(':', 1)
                if section_name not in all_sections:
                    raise KeyError(f"Section '{section_name}' not found")
                if key_name not in all_sections[section_name]:
                    raise KeyError(f"Key '{key_name}' not found in section '{section_name}'")
                replacement = all_sections[section_name][key_name]
            else:
                # ${key}
                # Check current section first, then DEFAULT
                if section not in all_sections:
                    raise KeyError(f"Section '{section}' not found")
                if match in all_sections[section]:
                    replacement = all_sections[section][match]
                elif match in default_section:
                    replacement = default_section[match]
                else:
                    raise KeyError(f"Key '{match}' not found in section '{section}' or DEFAULT")

            # Replace with interpolated value
            value = value.replace(f'${{{match}}}', replacement)

            # Check for cycles
            if '${' in value:
                # Recursive interpolation
                return interpolate_value(value, section, all_sections)

        return value

    # Helper to handle continuation lines
    def handle_continuation(lines: List[str], i: int, section: str, key: str, current_value: str) -> Tuple[int, str]:
        while i < len(lines):
            line = lines[i]
            i += 1
            stripped = line.strip()
            if not stripped:
                continue
            if stripped[0] in (';', '#'):
                continue
            if ' ;' in stripped or ' #' in stripped:
                # Remove inline comment
                in_quotes = False
                comment_start = -1
                for j, char in enumerate(stripped):
                    if char == '"':
                        in_quotes = not in_quotes
                    elif not in_quotes and (char == ';' or char == '#'):
                        if j > 0 and stripped[j-1] == ' ':
                            comment_start = j
                            break
                if comment_start != -1:
                    stripped = stripped[:comment_start].rstrip()

            if not stripped:
                continue

            # Check if this line starts with whitespace (continuation)
            if line.lstrip() != line:
                # This is a continuation line
                if stripped.startswith('"') and stripped.endswith('"'):
                    current_value += '\n' + stripped[1:-1]
                else:
                    current_value += '\n' + stripped
            else:
                # Not a continuation line, break
                break

        return i, current_value

    # Main parsing loop
    while i < len(lines):
        line = lines[i]
        i += 1

        # Skip empty lines or comments
        if is_comment_or_empty(line):
            continue

        # Check for section header
        if line.strip().startswith('[') and line.strip().endswith(']'):
            section_name = line.strip()[1:-1].strip()
            if section_name == 'DEFAULT':
                current_section = None
                # We'll handle DEFAULT separately
                continue
            else:
                current_section = section_name
                if current_section not in result:
                    result[current_section] = {}
                continue

        # If we're not in a section, and not DEFAULT, this is invalid
        if current_section is None and not line.strip().startswith('['):
            raise ValueError("Key line before any section header")

        # Parse key-value
        try:
            key, value = parse_key_value(line, current_section)
        except ValueError as e:
            raise ValueError(f"Malformed line: {e}")

        # Handle continuation lines
        if i < len(lines):
            next_line = lines[i]
            if next_line.strip() and next_line.lstrip() != next_line:
                # Next line starts with whitespace -> continuation
                i, value = handle_continuation(lines, i, current_section, key, value)

        # Interpolate value
        try:
            value = interpolate_value(value, current_section, result)
        except KeyError as e:
            raise KeyError(str(e))
        except ValueError as e:
            raise ValueError(str(e))

        # Store in current section or DEFAULT
        if current_section is None:
            # This is a key in DEFAULT section
            default_section[key] = value
        else:
            # Store in current section, overwrite if key exists
            result[current_section][key] = value

    # Apply DEFAULT inheritance to all sections
    for section_name, section in result.items():
        for key, value in default_section.items():
            if key not in section:
                section[key] = value

    return result
